<section class="garden-panel" id="project-tasks"><div class="garden-panel-heading"><div><span class="garden-kicker">MAKE THE WORK VISIBLE</span><h2>Team task board</h2></div><span class="garden-muted"><?= count($garden_tasks); ?> task cards</span></div><p class="garden-muted garden-panel-intro">Plan the practical work here. Complete the project separately after customer sign-off and invoice settlement.</p>
<?php if ($garden_workbench_ready && $editable): ?><details class="garden-record-compose"><summary class="garden-create-summary"><span><i class="fa fa-plus" aria-hidden="true"></i> Add a task</span></summary><form method="post" action="<?= base_url('garden/project_task'); ?>"><?php $this->load->view('garden/form_token'); ?><input type="hidden" name="job_id" value="<?= $jobId; ?>"><input type="hidden" name="request_key" value="<?= bin2hex(random_bytes(20)); ?>"><label>Task title<input name="title" required maxlength="200" placeholder="e.g. Test soil and mark planting beds"></label><div class="garden-grid"><label>Assigned team member<select name="assigned_user_id" data-garden-select hidden><option value="">Unassigned</option><?php foreach ($garden_staff as $staff): ?><option value="<?= (int)$staff->id; ?>"><?= htmlspecialchars($staff->username); ?></option><?php endforeach; ?></select></label><label>Due date<input type="date" name="due_date"></label></div><label>Instructions<textarea id="garden-task-instructions" name="description" rows="3" maxlength="8000"></textarea></label><?php $this->load->view('garden/voice_button',['voice_target'=>'garden-task-instructions']); ?><button class="garden-button">Add task card</button></form></details><?php endif; ?>
<div class="garden-kanban garden-task-board" aria-label="Project team task board"><?php foreach (['todo'=>'To do','in_progress'=>'In progress','completed'=>'Completed'] as $status=>$label): $tasks=array_filter($garden_tasks,function($task) use($status){return $task->status===$status;}); ?><section class="garden-kanban-lane" data-task-lane="<?= $status; ?>"><div class="garden-lane-heading"><span><i class="garden-stage-dot garden-dot-<?= $status; ?>"></i><?= $label; ?></span><b><?= count($tasks); ?></b></div><div class="garden-lane-body"><?php foreach ($tasks as $task): ?><article class="garden-task-tile" data-task-card="<?= (int)$task->id; ?>" <?= $editable ? 'draggable="true"' : ''; ?>><h3><?= htmlspecialchars($task->title); ?></h3><p><?= nl2br(htmlspecialchars($task->description ?? '')); ?></p><small><i class="fa fa-user-o" aria-hidden="true"></i> <?= htmlspecialchars($task->assignee ?: 'Unassigned'); ?><?php if ($task->due_date): ?> · Due <?= htmlspecialchars($task->due_date); ?><?php endif; ?></small>
<?php if ($editable): ?><form method="post" action="<?= base_url('garden/project_task_move'); ?>"><?php $this->load->view('garden/form_token'); ?><input type="hidden" name="job_id" value="<?= $jobId; ?>"><input type="hidden" name="task_id" value="<?= (int)$task->id; ?>"><input type="hidden" name="version" value="<?= (int)$task->version; ?>"><div class="garden-task-actions"><?php foreach (['todo'=>'To do','in_progress'=>'Start','completed'=>'Complete'] as $to=>$action): if ($to===$status) continue; ?><button type="submit" name="status" value="<?= $to; ?>"><?= $action; ?></button><?php endforeach; ?></div></form><?php endif; ?></article><?php endforeach; ?><?php if (!$tasks): ?><p class="garden-lane-empty">No tasks here yet.</p><?php endif; ?></div></section><?php endforeach; ?></div></section>
